templates.template:
// CloudCheats Profile Layout v2

.cc-profile-wrap {
    max-width: 100%;
}

// ── Header / Cover ────────────────────────────────────────────────────────────

.cc-profile-cover {
    position: relative;
    border-radius: @xf-borderRadius;
    overflow: hidden;
    margin-bottom: 0;
}

.cc-profile-banner-bg {
    position: relative;
    min-height: 200px;
    background: linear-gradient(135deg, hsl(230, 38%, 13%) 0%, hsl(222, 30%, 15%) 60%, hsl(215, 45%, 18%) 100%);
    display: block;
}

.cc-profile-banner-bg::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, transparent 30%, rgba(0,0,0,.65) 100%);
    pointer-events: none;
}

.cc-profile-header {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: flex-end;
    gap: 18px;
    padding: 0 20px 20px;
    flex-wrap: wrap;
}

// ── Avatar ring (colored border) ──────────────────────────────────────────────

.cc-avatar-ring {
    flex-shrink: 0;
    margin-bottom: -14px;
    padding: 3px;
    border-radius: 14px;
    background: linear-gradient(135deg, rgba(80,100,255,.9) 0%, rgba(160,60,255,.9) 100%);
    display: inline-block;
}

.cc-avatar-ring .avatarWrapper {
    display: block;
}

.cc-avatar-ring .avatar {
    width: 130px !important;
    height: 130px !important;
    border-radius: 10px !important;
    border: none !important;
    display: block;
}

.cc-avatar-ring .avatar--image {
    width: 130px;
    height: 130px;
    object-fit: cover;
    border-radius: 10px;
}

.cc-avatar-ring .avatarWrapper-update {
    border-radius: 0 0 8px 8px;
    font-size: 0.75em;
}

// ── Header text / actions ────────────────────────────────────────────────────

.cc-profile-header-info {
    flex: 1;
    min-width: 200px;
    padding-bottom: 6px;
}

.cc-profile-username {
    font-size: 1.7em;
    font-weight: 700;
    color: #fff;
    text-shadow: 0 1px 4px rgba(0,0,0,.6);
    margin: 0 0 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.cc-profile-username .username,
.cc-profile-username a {
    color: inherit !important;
    text-shadow: inherit;
}

.cc-profile-blurb {
    color: rgba(255,255,255,.75);
    font-size: 0.9em;
    margin-bottom: 10px;
}

.cc-profile-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.cc-profile-admin-row {
    margin-top: auto;
    padding-bottom: 6px;
}

// ── Three-column body ─────────────────────────────────────────────────────────

.cc-profile-body {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 0 0;
}

@media (max-width: 768px) {
    .cc-profile-body { flex-direction: column; }
    .cc-profile-sidebar { width: 100% !important; }
    .cc-profile-right { width: 100% !important; }
}

// ── Left sidebar ─────────────────────────────────────────────────────────────

.cc-profile-sidebar {
    width: 230px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cc-sidebar-card {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: @xf-borderRadius;
}

// Big online / offline status card
.cc-status-card {
    padding: 14px 16px;
}

.cc-status-main {
    display: flex;
    align-items: center;
    gap: 9px;
}

.cc-status-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
}

.cc-status-label {
    font-size: 1.05em;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.cc-status-activity {
    font-size: 0.78em;
    color: @xf-textColorMuted;
    margin-top: 5px;
    line-height: 1.4;
}

.cc-status--online .cc-status-dot {
    background: #22c55e;
    box-shadow: 0 0 7px rgba(34,197,94,.75);
}

.cc-status--online .cc-status-label {
    color: #22c55e;
}

.cc-status--offline .cc-status-dot {
    background: @xf-textColorMuted;
}

.cc-status--offline .cc-status-label {
    color: @xf-textColorMuted;
}

// Reputation / Points side-by-side mini stats
.cc-mini-stats-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1px;
    background: @xf-borderColor;
    border: 1px solid @xf-borderColor;
    border-radius: @xf-borderRadius;
    overflow: hidden;
}

.cc-mini-stat {
    background: @xf-contentBg;
    padding: 12px 8px;
    text-align: center;
}

.cc-mini-stat-val {
    font-size: 1.3em;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 4px;
}

.cc-mini-stat-label {
    font-size: 0.7em;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: @xf-textColorMuted;
}

// YOS badge card
.cc-yos-sidebar-card {
    padding: 12px 16px;
}

.cc-yos-sidebar-card .dp-service-badge-profile {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    border-radius: 20px;
    font-size: 0.85em;
    font-weight: 700;
    width: 100%;
    box-sizing: border-box;
    justify-content: center;
}

.cc-yos-sidebar-card .dp-service-badge-icon {
    position: relative;
    width: 27px;
    height: 19px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.cc-yos-sidebar-card .service-badge-svg {
    position: absolute;
    top: 0; left: 0;
    width: 27px; height: 19px;
}

.cc-yos-sidebar-card .service-badge-svg-bg { display: none; }

.cc-yos-sidebar-card .dp-service-badge-duration {
    font-size: 1.3em;
    font-weight: 800;
}

.cc-yos-sidebar-card .dp-service-badge-title {
    font-size: 0.8em;
    opacity: .85;
}

.cc-yos-sidebar-card.year-1 .dp-service-badge-profile  { background: rgba(180,140,100,.15); color: #b48c64; border: 1px solid #b48c64; }
.cc-yos-sidebar-card.year-2 .dp-service-badge-profile  { background: rgba(160,160,170,.15); color: #a0a0aa; border: 1px solid #a0a0aa; }
.cc-yos-sidebar-card.year-3 .dp-service-badge-profile  { background: rgba(255,215,  0,.15); color: #ffd700; border: 1px solid #ffd700; }
.cc-yos-sidebar-card.year-4 .dp-service-badge-profile  { background: rgba(180,235,255,.15); color: #b4ebff; border: 1px solid #b4ebff; }
.cc-yos-sidebar-card.year-5 .dp-service-badge-profile  { background: rgba(255,165,  0,.15); color: #ffa500; border: 1px solid #ffa500; }
.cc-yos-sidebar-card.year-6 .dp-service-badge-profile  { background: rgba(160,200,255,.15); color: #a0c8ff; border: 1px solid #a0c8ff; }
.cc-yos-sidebar-card.year-7 .dp-service-badge-profile  { background: rgba(220,160,255,.15); color: #dca0ff; border: 1px solid #dca0ff; }
.cc-yos-sidebar-card.year-8 .dp-service-badge-profile  { background: rgba(255,100,100,.15); color: #ff6464; border: 1px solid #ff6464; }
.cc-yos-sidebar-card.year-9 .dp-service-badge-profile  { background: rgba( 80,200,120,.15); color: #50c878; border: 1px solid #50c878; }
.cc-yos-sidebar-card.year-10 .dp-service-badge-profile { background: rgba(255,215,  0,.20); color: #ffd700; border: 2px solid #ffd700; box-shadow: 0 0 12px rgba(255,215,0,.4); }

// Info rows
.cc-info-card {
    padding: 8px 14px;
}

.cc-info-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 6px;
    padding: 6px 0;
    border-bottom: 1px solid @xf-borderColorFaint;
    font-size: 0.82em;
}

.cc-info-row:last-child {
    border-bottom: none;
}

.cc-info-label {
    color: @xf-textColorMuted;
    font-weight: 600;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 4px;
}

.cc-info-val {
    text-align: right;
    word-break: break-word;
    color: @xf-textColor;
}

// ── Center content ────────────────────────────────────────────────────────────

.cc-profile-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cc-stats-card {
    background: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    border-radius: @xf-borderRadius;
    overflow: hidden;
}

.cc-stats-grid .pairJustifier {
    display: flex;
    flex-wrap: wrap;
}

.cc-stats-grid dl.pairs {
    display: flex;
    flex-direction: column-reverse;
    align-items: center;
    justify-content: center;
    text-align: center;
    flex: 1 1 90px;
    padding: 14px 8px;
    border-right: 1px solid @xf-borderColor;
    border-bottom: 1px solid @xf-borderColor;
    margin: 0;
    min-width: 80px;
}

.cc-stats-grid dl.pairs:last-child {
    border-right: none;
}

.cc-stats-grid dl.pairs dd {
    font-size: 1.35em;
    font-weight: 700;
    margin: 0 0 2px;
}

.cc-stats-grid dl.pairs dd a {
    color: inherit;
    font-size: inherit;
    font-weight: inherit;
}

.cc-stats-grid dl.pairs dt {
    font-size: 0.68em;
    text-transform: uppercase;
    letter-spacing: .05em;
    color: @xf-textColorMuted;
}

.cc-profile-content .block-tabHeader.tabs {
    margin-bottom: 0;
    border-radius: @xf-borderRadius @xf-borderRadius 0 0;
}

.cc-profile-content .block {
    border-radius: 0 0 @xf-borderRadius @xf-borderRadius;
    margin-top: 0;
}

.cc-profile-content .tabPanes {
    margin: 0;
    padding: 0;
    list-style: none;
}

.cc-profile-content .p-adPlaceholder {
    margin: 0;
}

// ── Right sidebar ─────────────────────────────────────────────────────────────

.cc-profile-right {
    width: 190px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cc-right-banners {
    padding: 12px;
}

.cc-right-card-title {
    font-size: 0.75em;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: @xf-textColorMuted;
    margin-bottom: 10px;
}

.cc-right-banners .userBanners,
.cc-right-banners .memberTooltip-banners {
    display: flex;
    flex-direction: column;
    gap: 6px;
    align-items: flex-start;
}

.cc-right-banners .userBanner {
    width: 100%;
    max-width: 100%;
}

.cc-right-banners img {
    max-width: 100%;
    border-radius: 4px;
}
